SELECT request_id, tenant_id, source_system, source_event_key,
        notification_template_id, default_locale, default_parameters, notification_route_id, create_time, update_time
        FROM t_notification_request WHERE request_id = #{id}

SELECT request_id, tenant_id, source_system, source_event_key,
        notification_template_id, default_locale, default_parameters, notification_route_id, create_time, update_time
        FROM t_notification_request WHERE source_system = #{sourceSystem} AND source_event_key = #{sourceEventKey}
